(function () {
    const STORAGE_KEY = 'uhz_modo_ia_activo';

    function leerEstado() {
        try {
            return localStorage.getItem(STORAGE_KEY) === '1';
        } catch (error) {
            return false;
        }
    }

    function guardarEstado(value) {
        try {
            localStorage.setItem(STORAGE_KEY, value ? '1' : '0');
        } catch (error) {
            /* El modo sigue funcionando aunque el navegador bloquee localStorage. */
        }
    }

    function pintarEstado() {
        const button = document.getElementById('uhzModoIA');
        const note = document.getElementById('uhzModoIANota');
        if (!button) return;

        const active = Boolean(window.uhzModoIAActivo);
        button.classList.toggle('is-active', active);
        button.setAttribute('aria-pressed', String(active));

        if (note) {
            note.textContent = active
                ? 'La b\xFAsqueda se realizar\xE1 dentro de UNIVERSHZRW y podr\xE1 ampliarse a servicios de terceros.'
                : 'Busca primero dentro de UNIVERSHZRW.';
        }
    }

    window.toggleModoIAUHZ = function () {
        window.uhzModoIAActivo = !window.uhzModoIAActivo;
        guardarEstado(window.uhzModoIAActivo);
        pintarEstado();

        if (typeof window.mostrarToast === 'function') {
            window.mostrarToast(
                window.uhzModoIAActivo
                    ? 'Modo IA activado: la b\xFAsqueda abarcar\xE1 UNIVERSHZRW y servicios de terceros.'
                    : 'Modo IA desactivado.'
            );
        }
    };

    document.addEventListener('DOMContentLoaded', function () {
        window.uhzModoIAActivo = leerEstado();
        pintarEstado();
    });
})();
`,type:"application/javascript"},"/_uhz/site-script-878c788f89b1.js":{body:`
(function () {
    let reconocimientoUHZ = null;
    let escuchandoUHZ = false;

    function obtenerReconocimientoUHZ() {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        if (!SpeechRecognition) return null;

        const recognition = new SpeechRecognition();
        recognition.lang = 'es-MX';
        recognition.interimResults = false;
        recognition.continuous = false;
        recognition.maxAlternatives = 1;

        recognition.onstart = function () {
            escuchandoUHZ = true;
            const button = document.getElementById('uhzBusquedaVoz');
            button?.classList.add('is-listening');
            button?.setAttribute('aria-label', 'Escuchando b\xFAsqueda por voz');
            const label = button?.querySelector('.uhz-voice-label');
            if (label) label.textContent = 'Escuchando';
        };

        recognition.onresult = function (event) {
            const transcript = event.results?.[0]?.[0]?.transcript?.trim() || '';
            const input = document.getElementById('inputBusqueda');
            if (input && transcript) {
                input.value = transcript;
                input.dispatchEvent(new Event('input', { bubbles: true }));
                input.focus();
            }
        };

        recognition.onerror = function (event) {
            if (typeof window.mostrarToast === 'function') {
                const message = event.error === 'not-allowed'
                    ? 'El navegador no permiti\xF3 usar el micr\xF3fono.'
                    : 'No fue posible reconocer la voz. Intenta nuevamente.';
                window.mostrarToast(message);
            }
        };

        recognition.onend = function () {
            escuchandoUHZ = false;
            const button = document.getElementById('uhzBusquedaVoz');
            button?.classList.remove('is-listening');
            button?.setAttribute('aria-label', 'Buscar por voz');
            const label = button?.querySelector('.uhz-voice-label');
            if (label) label.textContent = 'Voz';
        };

        return recognition;
    }

    window.iniciarBusquedaVozUHZ = function () {
        if (escuchandoUHZ && reconocimientoUHZ) {
            reconocimientoUHZ.stop();
            return;
        }

        if (!reconocimientoUHZ) reconocimientoUHZ = obtenerReconocimientoUHZ();

        if (!reconocimientoUHZ) {
            if (typeof window.mostrarToast === 'function') {
                window.mostrarToast('La b\xFAsqueda por voz no est\xE1 disponible en este navegador.');
            }
            return;
        }

        try {
            reconocimientoUHZ.start();
        } catch (error) {
            reconocimientoUHZ.stop();
        }
    };
})();
