        function addCartUHZ(id,variant='',qty=1){const p=productByIdUHZ(id);if(!p||!p.available)return;const vars=Array.isArray(p.variants)?p.variants:[];if(vars.length&&(!variant||!vars.includes(variant))){openProductDetailUHZ(id);return}const min=Math.max(1,Number(p.minQuantity||1)),max=Math.max(0,Math.min(Number(p.maxQuantity||20),p.trackStock?Number(p.stock):100)),q=Math.max(min,Math.min(max,Math.floor(Number(qty||1)))),key=String(id)+'::'+String(variant||''),row=shop.cart.find(x=>cartKeyUHZ(x)===key);if(row)row.quantity=Math.min(max,Number(row.quantity||0)+q);else shop.cart.push({id:String(id),variant:String(variant||''),quantity:q});persistCartUHZ();showShopMessageUHZ(p.name+' agregado al carrito.','ok')}
