        function cartSummaryUHZ(){let subtotal=0,shipping=0,count=0,needsShipping=false,allowMp=true,allowSpei=true,maxInst=24;const valid=[];for(const item of shop.cart){const p=productByIdUHZ(item.id);if(!p||!p.available)continue;const q=Math.max(1,Number(item.quantity||1));subtotal+=Number(p.price||0)*q;shipping+=Number(p.shippingCost||0)*q;count+=q;needsShipping=needsShipping||!!p.requiresShipping;allowMp=allowMp&&!!p.allowMercadoPago;allowSpei=allowSpei&&!!p.allowSpei;maxInst=Math.min(maxInst,Number(p.maxInstallments||1));valid.push({item,p,q})}return {subtotal,shipping,total:subtotal+shipping,count,needsShipping,allowMp,allowSpei,maxInst:maxInst===24&&valid.length===0?1:maxInst,valid}}
