        function ejecutarBusquedaRapidaUHZ() {
            const contenedor = document.getElementById('contenedorResultados');
            const estado = document.getElementById('estadoResultados');
            const frase = normalizarTexto(consultaActual).trim();
            const todosLosTerminos = frase.split(/\\s+/).filter(Boolean);
            let terminos = todosLosTerminos.filter(term => !UHZ_STOPWORDS_BUSQUEDA.has(term));
            if (!terminos.length) terminos = todosLosTerminos;
            if (!terminos.length) return;

            const ranked = [];
            for (let index = 0; index < documentos.length; index++) {
                const doc = documentos[index];
                const score = scoreDocumentoUHZ(doc, terminos, frase);
                if (score >= 0) ranked.push({ doc, index, score });
            }
            ranked.sort((a, b) => b.score - a.score || a.index - b.index);
            const resultados = ranked.map(item => item.doc);

            if (!resultados.length && ejecutarBusquedaBaseUHZ) {
                return ejecutarBusquedaBaseUHZ();
            }

            uhzResultadosActuales = resultados;
            if (estado) estado.textContent = resultados.length + ' resultado(s) \xB7 b\xFAsqueda instant\xE1nea';
            if (contenedor) renderizarLoteResultadosUHZ(true);
        }

        try {
            cargarDatos = cargarDatosRapidaUHZ;
            window.cargarDatos = cargarDatosRapidaUHZ;
            ejecutarBusquedaReal = ejecutarBusquedaRapidaUHZ;
            window.ejecutarBusquedaReal = ejecutarBusquedaRapidaUHZ;
        } catch (_) {
            window.cargarDatos = cargarDatosRapidaUHZ;
            window.ejecutarBusquedaReal = ejecutarBusquedaRapidaUHZ;
        }

