 const detail=window.orderDetailsUHZ;
 window.orderDetailsUHZ=async function(folio){await detail(folio);const host=document.querySelector('#modalHost .modal-body');if(!host)return;const {data:r,error}=await sb.from('shop_orders').select('order_snapshot').eq('folio',folio).maybeSingle();if(error||!r?.order_snapshot?.terms_version)return;const snapshot=r.order_snapshot,box=document.createElement('section');box.className='notice';const add=(tag,text)=>{const x=document.createElement(tag);x.textContent=text;box.append(x)};add('h4','Constancia de condiciones y entrega');add('p','Versi\xF3n: '+snapshot.terms_version+' \xB7 Aceptaci\xF3n recibida: '+snapshot.accepted_at);add('p','Huella SHA-256: '+snapshot.terms_sha256);if(snapshot.digital_delivery_email)add('p','Correo de entrega digital: '+snapshot.digital_delivery_email);for(const item of snapshot.item_contracts||[]){add('p',item.name+' \xB7 '+item.quantity+' \xD7 $'+item.unit_price+' \xB7 '+(item.delivery||''));if(item.digital_format)add('p','Formato: '+item.digital_format);if(item.digital_license)add('p','Licencia: '+item.digital_license)}add('small','Registro de la operaci\xF3n. No constituye certificaci\xF3n jur\xEDdica, firma electr\xF3nica certificada ni constancia NOM-151.');host.append(box)};
