(()=>{
function edEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function edParts(value){const sections=[];let current=null;for(const line of String(value||'').slice(0,24000).split(/\\r?\\n/)){if(/^##\\s+/.test(line)){current={title:line.replace(/^##\\s+/,''),text:[]};sections.push(current);}else{if(!current){current={title:'Presentaci\xF3n',text:[]};sections.push(current);}current.text.push(line);}}return sections.map(s=>({...s,text:s.text.join('\\n').trim()})).filter(s=>s.text);}
function edArticle(doc){const title=String(doc?.bloqueTitulo||'');return /^Art\xEDculo editorial\\s*:/i.test(title)?{title:title.replace(/^Art\xEDculo editorial\\s*:\\s*/i,''),body:String(doc.bloqueContenido||'')}:null;}
function edReview(body){const parts=edParts(body),words=String(body||'').trim().split(/\\s+/).filter(Boolean).length;const missing=[];if(String(body||'').trim().length<800)missing.push('Desarrolla una explicaci\xF3n propia; el cuerpo es todav\xEDa breve.');if(parts.filter(s=>s.text.length>=60).length<3)missing.push('Desarrolla al menos tres apartados con informaci\xF3n espec\xEDfica.');if(/\\[(?:Escribe|Completa|A\xF1ade|Describe|Explica)[^\\]]*\\]/i.test(body||''))missing.push('Sustituye las indicaciones de la plantilla por tu contenido.');return {words,sections:parts.length,ready:!missing.length,missing};}
function edMarkup(body,level=3){return edParts(body).map((s,i)=>'<section class="uhz-ed-section" id="apartado-'+i+'"><h'+level+'>'+edEscape(s.title)+'</h'+level+'>'+s.text.split(/\\n\\s*\\n/).filter(Boolean).map(p=>'<p>'+edEscape(p).replace(/\\n/g,'<br>')+'</p>').join('')+'</section>').join('');}
function edPath(id){return '/biblioteca/'+encodeURIComponent(String(id));}

if(typeof tableDefs!=='undefined'&&tableDefs.content_resources&&typeof window.openEditor==='function'){
 const fields=tableDefs.content_resources.fields;
 for(const f of [['block_title','T\xEDtulo del art\xEDculo \xB7 comienza con \xABArt\xEDculo editorial:\xBB','text'],['block_content','Art\xEDculo original \xB7 apartados con ## y p\xE1rrafos separados por una l\xEDnea vac\xEDa','textarea'],['block_button','Texto del bot\xF3n de referencia','text']])if(!fields.some(x=>x[0]===f[0]))fields.push(f);
 const openBefore=window.openEditor;
 window.openEditor=function(table,row){openBefore(table,row);if(table!=='content_resources')return;const host=document.getElementById('modalHost'),body=host.querySelector('[data-field=block_content]'),title=host.querySelector('[data-field=block_title]');if(!body||!title)return;body.rows=18;body.maxLength=24000;
  const pane=document.createElement('section');pane.className='uhz-ed-assistant';const h=document.createElement('h4');h.textContent='Prepara una ficha con contenido propio';const note=document.createElement('p');note.textContent='Estos controles ayudan a redactar. No verifican originalidad, permisos ni aprobaci\xF3n de AdSense. Publica solo informaci\xF3n que puedas sostener.';
  const select=document.createElement('select');select.setAttribute('aria-label','Tipo de gu\xEDa editorial');for(const [v,t]of [['general','Documento o gu\xEDa'],['software','Aplicaci\xF3n o software'],['cine','Pel\xEDcula o serie'],['original','Creaci\xF3n original']]){const o=document.createElement('option');o.value=v;o.textContent=t;select.append(o);}if(/pel[i\xED]cula|serie/i.test(row?.content_type||''))select.value='cine';
  const suggestions={general:['Qu\xE9 resuelve y para qui\xE9n','Explicaci\xF3n y contexto','Ejemplo explicado','L\xEDmites y precauciones','Fuentes y derechos'],software:['Qu\xE9 problema resuelve','Requisitos y compatibilidad comprobados','C\xF3mo se usa \xB7 pasos comprobados','Ventajas y l\xEDmites observados','Fuentes, versi\xF3n y licencia'],cine:['Premisa sin spoilers','Contexto y datos con fuente','Lectura editorial \xB7 distingue hechos y opiniones','Preguntas para conversar','Disponibilidad y derechos','Fuentes consultadas'],original:['Qu\xE9 has creado y para qui\xE9n','Proceso y decisiones propias','Ejemplo de aplicaci\xF3n','L\xEDmites y condiciones de uso','Autor\xEDa, permisos y fuentes']};
  const button=document.createElement('button');button.type='button';button.textContent='Crear esquema si el art\xEDculo est\xE1 vac\xEDo';button.onclick=()=>{if(body.value.trim()){output.textContent='Se conserv\xF3 el texto existente. Puedes a\xF1adir tus apartados manualmente.';return;}body.value=suggestions[select.value].map(t=>'## '+t+'\\n\\n[Escribe informaci\xF3n propia y espec\xEDfica para este apartado.]').join('\\n\\n');if(!title.value.trim())title.value='Art\xEDculo editorial: '+(host.querySelector('[data-field=title]')?.value||'Nueva aportaci\xF3n');body.dispatchEvent(new Event('input',{bubbles:true}));};
  const output=document.createElement('output');output.setAttribute('aria-live','polite');const update=()=>{const r=edReview(body.value);output.textContent=r.words+' palabras \xB7 '+r.sections+' apartados. '+(r.ready?'Estructura desarrollada; faltan comprobaci\xF3n editorial y derechos.':r.missing.join(' '));};body.addEventListener('input',update);pane.append(h,note,select,button,output);body.parentElement.before(pane);update();
 };
 const saveBefore=window.saveEditor;
 window.saveEditor=function(table,id){if(table==='content_resources'){const host=document.getElementById('modalHost'),title=host.querySelector('[data-field=block_title]')?.value||'',body=host.querySelector('[data-field=block_content]')?.value||'',published=host.querySelector('[data-field=publish]')?.value==='true';if(published&&/^Art\xEDculo editorial\\s*:/i.test(title)&&!edReview(body).ready){const s=document.getElementById('editorState');s.textContent='Completa el art\xEDculo antes de publicarlo. '+edReview(body).missing.join(' ');s.className='notice bad';return;}}return saveBefore(table,id);};
}

})();
