    const identity=document.createElement('div');identity.className='uhz-phone-account-identity';const identityName=document.createElement('strong');const identityNote=document.createElement('span');identity.append(identityName,identityNote);
    const accountLinks=document.createElement('nav');accountLinks.className='uhz-phone-account-links';accountLinks.setAttribute('aria-label','Opciones de mi cuenta');accountSheet.append(accountHead,identity,accountLinks);root.append(accountSheet);
