    const title = document.createElement('h2'); title.id = 'uhz-mobile-sheet-title'; title.textContent = 'Tu UNIVERSHZRW';
    const dismiss = button('\xD7', () => sheet.close(), 'uhz-phone-dismiss'); dismiss.setAttribute('aria-label', 'Cerrar men\xFA');
    head.append(title, dismiss);
