    // Yield the bottom of the viewport to the original sponsored banner.
    // This only changes OUR navigation. The advertising DOM and styles are untouched.
    const sponsor = document.getElementById('uhzFooterAdBanner');
    const searchInput = document.getElementById('inputBusqueda');
    const originalPlaceholder = searchInput?.getAttribute('placeholder');
    function sync() {
      if (searchInput) searchInput.placeholder = phone.matches ? 'Buscar en UNIVERSHZRW' : originalPlaceholder || '';
      const r = sponsor?.getBoundingClientRect();
      const visible = !!sponsor && !sponsor.hidden && r?.height > 0 && getComputedStyle(sponsor).display !== 'none' && getComputedStyle(sponsor).visibility !== 'hidden';
      const next = phone.matches && visible;
      if (document.body.classList.contains('uhz-phone-sponsor-visible') !== next) document.body.classList.toggle('uhz-phone-sponsor-visible', next);
      if (!phone.matches && sheet.open) sheet.close();
    }
    const observer = new MutationObserver(sync);
    if (sponsor) observer.observe(sponsor, { attributes: true, attributeFilter: ['hidden', 'style', 'class'], childList: true });
