  const summary=root.querySelector('.uhz-txt-panel.soft h3');if(summary)summary.textContent='Resumen del recurso';
  const video=root.querySelector('.uhz-video-link');if(video&&!doc.videoTutorial){const parent=video.parentElement;video.remove();parent.classList.add('uhz-ed-single');}else if(video){video.querySelector('h4').textContent='Video aportado';video.querySelector('p').textContent='Enlace externo indicado en esta ficha.';}
  for(const panel of root.querySelectorAll('.uhz-txt-panel'))if(['Verificaci\xF3n correcta','Puntos clave'].includes(panel.querySelector('h4')?.textContent))panel.remove();
