          const oldPill=overlay.querySelector('.uhz-shop-cart-pill'),cartButton=document.createElement('button');cartButton.type='button';cartButton.className='uhz-shop-cart-pill';cartButton.setAttribute('aria-label','Abrir carrito');cartButton.setAttribute('aria-controls','storeCartDialog');cartButton.setAttribute('aria-haspopup','dialog');cartButton.innerHTML=cartIconUHZ+'<span>Carrito</span><b id="uhzShopCartCount">0</b>';oldPill.replaceWith(cartButton);cartButton.addEventListener('click',openCartUHZ);
          document.getElementById('storeCartClose').addEventListener('click',closeCartUHZ);dialog.addEventListener('click',e=>{if(e.target===dialog)closeCartUHZ()});dialog.addEventListener('close',()=>cartReturnFocus?.focus?.());
          document.getElementById('storeCartNext').addEventListener('click',()=>{if(cartStage==='items')cartStepUHZ('delivery');else if(validateDeliveryUHZ()){renderOrderReviewUHZ();cartStepUHZ('review')}});document.getElementById('storeCartBack').addEventListener('click',()=>cartStepUHZ(cartStage==='review'?'delivery':'items'));
          const bar=document.createElement('div');bar.className='store-cart-bar';bar.hidden=true;bar.innerHTML='<button type="button" aria-label="Ver carrito">'+cartIconUHZ+'<span id="storeCartBarCount"></span><strong id="storeCartBarTotal"></strong><span aria-hidden="true">\u2192</span></button>';bar.querySelector('button').addEventListener('click',openCartUHZ);overlay.querySelector('.uhz-shop-shell').append(bar);
          const message=document.createElement('div');message.id='uhzShopMessage';message.className='uhz-shop-message';message.setAttribute('role','status');message.setAttribute('aria-live','polite');overlay.querySelector('.uhz-shop-catalog').append(message);
          overlay.addEventListener('click',e=>{const b=e.target.closest('[data-store-view]');if(b){storeFilter=b.dataset.storeView;renderProductsUHZ()}if(e.target.closest('[data-store-retry]'))void loadShopUHZ(true);if(e.target.closest('[data-store-reset]')){storeFilter='all';input.value='';document.getElementById('uhzShopCategory').value='';renderProductsUHZ()}const remove=e.target.closest('[data-store-remove]');if(remove){shop.cart=shop.cart.filter(x=>cartKeyUHZ(x)!==remove.dataset.storeRemove);persistCartUHZ()}});
