          document.getElementById('storeDigitalConsent').hidden=!flags.digital;document.getElementById('storeDigitalAccepted').required=flags.digital&&shop.config.checkoutActive&&!flags.demo;
          document.getElementById('storePrivacyLabel').textContent=flags.demo?'He le\xEDdo el uso de datos de esta simulaci\xF3n (no se env\xEDan).':'Acepto el uso de mis datos para atender este pedido.';document.getElementById('storeTermsLabel').textContent=flags.demo?'He revisado las condiciones de ejemplo (sin contratar).':'He revisado productos, importes y condiciones de entrega.';
          document.getElementById('uhzShopPrivacyConsent').required=shop.config.checkoutActive&&!flags.demo;document.getElementById('uhzShopTermsConsent').required=shop.config.checkoutActive&&!flags.demo;
          const terms=document.getElementById('storeTermsText');terms.replaceChildren();for(const [key,text]of Object.entries(shop.config.terms||{})){if(key==='version')continue;const p=document.createElement('p');p.textContent=text;terms.append(p)}
          const ready=shop.config.checkoutActive&&!flags.demo&&!flags.pendingDigital&&!flags.pendingShipping,mpOk=ready&&!!shop.config.payments?.mercadoPago&&sum.allowMp,spOk=ready&&!!shop.config.payments?.spei&&sum.allowSpei;
          document.querySelector('#uhzPayMPLabel input').disabled=!mpOk;document.querySelector('#uhzPaySpeiLabel input').disabled=!spOk;document.getElementById('uhzPayChoices').hidden=!ready;const pay=document.getElementById('uhzShopPay');pay.disabled=!sum.count||(!mpOk&&!spOk);pay.textContent=flags.demo?'Ejemplo \xB7 no se realizan cobros':ready?'Continuar al pago':'Compras todav\xEDa no disponibles';
          document.getElementById('storePaymentReadiness').textContent=flags.demo?'Los ejemplos sirven para probar el carrito y la entrega. No generan pedidos ni cargos.':!shop.config.checkoutActive?'La tienda est\xE1 en preparaci\xF3n. Puedes revisar tu carrito y la entrega; todav\xEDa no se aceptan pagos.':flags.pendingShipping?'Falta confirmar el costo y plazo de env\xEDo.':flags.pendingDigital?'La entrega digital de alg\xFAn producto a\xFAn no est\xE1 preparada.':'';
          document.getElementById('storeCheckoutNotice').textContent=flags.demo?'Carrito de demostraci\xF3n \xB7 precios ilustrativos.':flags.pendingShipping?'El env\xEDo se confirmar\xE1 antes de habilitar el pago.':sum.count?'Revisa productos y datos de entrega antes de confirmar.':'';
